using System;using System.Diagnostics;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Threading;
public static class MemoryNativeQA {
 static int checks;static void Assert(bool value,string label){if(!value)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
 public static int Main(string[] args){string root=args[0],fixture=args[1];Directory.CreateDirectory(root);var json=new JavaScriptSerializer{MaxJsonLength=4*1024*1024};Process child=null;
  try{child=Process.Start(new ProcessStartInfo{FileName=fixture,UseShellExecute=false,RedirectStandardInput=true,RedirectStandardOutput=true,CreateNoWindow=true});Assert(child.StandardOutput.ReadLine()=="READY","owned fixture allocated 128 MiB");
   using(var service=new MemoryMaintenance(root)){
    var status=(MemoryMaintenance.Status)service.Request("memory.status",new Dictionary<string,object>{{"deviceId","local"}});Assert(status.snapshot.totalBytes>0&&status.snapshot.availableBytes<=status.snapshot.totalBytes,"real physical memory bounds");Assert(status.processes.Any(p=>p.pid==child.Id&&p.canTrim),"owned fixture eligible");Assert(status.processes.Any(p=>p.pid==Process.GetCurrentProcess().Id&&!p.canTrim),"current application excluded");Assert(!status.policy.enabled&&status.records.Count==0,"automatic policy off and no fabricated records");Console.WriteLine("STANDBY_AVAILABLE="+status.capabilities["standby"].available+" STANDBY_BYTES="+status.snapshot.standbyBytes);
    bool denied=false;try{service.Request("memory.status",new Dictionary<string,object>{{"deviceId","ssh-test"}});}catch(InvalidOperationException){denied=true;}Assert(denied,"remote cleanup rejected");
    var prepare=new Dictionary<string,object>{{"deviceId","local"},{"areas",new[]{"workset"}},{"pids",new[]{child.Id}}};
    var plan=(MemoryMaintenance.Confirmation)service.Request("memory.prepare",prepare);Assert(plan.processCount==1&&plan.processes[0].pid==child.Id,"plan pins only owned fixture identity");service.Request("memory.cancel",new Dictionary<string,object>{{"deviceId","local"},{"token",plan.token}});denied=false;try{service.Request("memory.execute",new Dictionary<string,object>{{"deviceId","local"},{"token",plan.token}});}catch(InvalidOperationException){denied=true;}Assert(denied,"cancelled token cannot execute");
    plan=(MemoryMaintenance.Confirmation)service.Request("memory.prepare",prepare);var result=(MemoryMaintenance.Record)service.Request("memory.execute",new Dictionary<string,object>{{"deviceId","local"},{"token",plan.token}});Assert(result.status=="success"&&result.results.Count==1&&result.results[0].succeeded==1,"real EmptyWorkingSet succeeds on owned fixture only");Assert(result.results[0].observedReductionBytes>32*1024*1024,"owned fixture resident pages decreased");Assert(!child.HasExited,"process not terminated");child.StandardInput.WriteLine("VERIFY");Assert(child.StandardOutput.ReadLine()=="VALID","allocated data still intact after trim");
    denied=false;try{service.Request("memory.execute",new Dictionary<string,object>{{"deviceId","local"},{"token",plan.token}});}catch(InvalidOperationException){denied=true;}Assert(denied,"confirmation token consumed exactly once");
    denied=false;try{service.Request("memory.prepare",new Dictionary<string,object>{{"deviceId","local"},{"areas",new[]{"standby","allstandby"}}});}catch(ArgumentException){denied=true;}Assert(denied,"overlapping standby selections rejected");
    denied=false;try{service.Request("memory.prepare",new Dictionary<string,object>{{"deviceId","local"},{"areas",new[]{"workset"}},{"pids",new[]{Process.GetCurrentProcess().Id}}});}catch(InvalidOperationException){denied=true;}Assert(denied,"current application cannot be trimmed by injected pid");
    var policy=new Dictionary<string,object>{{"deviceId","local"},{"enabled",false},{"threshold",83},{"durationMinutes",5},{"cooldownMinutes",30},{"areas",new[]{"workset"}}};service.Request("memory.policy.save",policy);status=(MemoryMaintenance.Status)service.Request("memory.status",new Dictionary<string,object>{{"deviceId","local"}});Assert(status.policy.threshold==83&&!status.policy.enabled,"disabled policy settings persist without executing");
    var handles=Process.GetCurrentProcess().HandleCount;for(int i=0;i<15;i++){var test=(MemoryMaintenance.Confirmation)service.Request("memory.prepare",prepare);service.Request("memory.cancel",new Dictionary<string,object>{{"deviceId","local"},{"token",test.token}});}Assert(Process.GetCurrentProcess().HandleCount<=handles+8,"repeated prepare/cancel releases pinned process handles");
    File.WriteAllText(Path.Combine(root,"native-result.json"),json.Serialize(new{checks=checks,result="PASS",reading=status.snapshot,processCount=status.processes.Count,record=result,systemCacheExecutionTested=false,fixturePid=child.Id}));
   }
   using(var reload=new MemoryMaintenance(root)){var saved=(MemoryMaintenance.Status)reload.Request("memory.status",new Dictionary<string,object>{{"deviceId","local"}});Assert(saved.records.Count==1&&saved.policy.threshold==83&&!saved.policy.enabled,"records and policy survive service recreation");}

   using(var reload=new MemoryMaintenance(root)){var saved=(MemoryMaintenance.Status)reload.Request("memory.status",new Dictionary<string,object>{{"deviceId","local"}});Assert(saved.cooldownSeconds>1700,"restart retains real operation cooldown");}
   var rule=new MemoryMaintenance.Policy{enabled=true,threshold=90,durationMinutes=1,cooldownMinutes=30};
   Assert(!MemoryMaintenance.PolicyReady(rule,89,90,3600),"below threshold never triggers");Assert(!MemoryMaintenance.PolicyReady(rule,95,59,3600),"sustained duration required");Assert(!MemoryMaintenance.PolicyReady(rule,95,90,1799),"cooldown prevents repeated automatic attempt");Assert(MemoryMaintenance.PolicyReady(rule,95,60,1800),"policy permits attempt only after duration and cooldown");rule.enabled=false;Assert(!MemoryMaintenance.PolicyReady(rule,99,900,9999),"disabled automatic policy never triggers");
   foreach(bool legacy in new[]{false,true}){string seeded=Path.Combine(root,legacy?"legacy-cooldown":"failed-cooldown");Directory.CreateDirectory(seeded);var initial=new MemoryMaintenance.State();initial.policy.enabled=false;if(legacy)initial.records.Add(new MemoryMaintenance.Record{timeUtc=DateTime.UtcNow.ToString("o"),before=new MemoryMaintenance.Reading(),after=new MemoryMaintenance.Reading(),status="failed"});else initial.lastAttemptUtc=DateTime.UtcNow.ToString("o");File.WriteAllText(Path.Combine(seeded,"memory-maintenance.json"),json.Serialize(initial));using(var reload=new MemoryMaintenance(seeded)){var saved=(MemoryMaintenance.Status)reload.Request("memory.status",new Dictionary<string,object>{{"deviceId","local"}});Assert(saved.cooldownSeconds>1700,legacy?"legacy record restores cooldown":"failed attempt without outcome retains cooldown");}}
   File.WriteAllText(Path.Combine(root,"native-summary.json"),json.Serialize(new{checks=checks,result="PASS",systemCacheExecutionTested=false,automaticExecutionTested=false,automaticPolicyGateTested=true}));
   Console.WriteLine("NATIVE_CHECKS="+checks);return 0;
  }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{if(child!=null){try{child.StandardInput.WriteLine("EXIT");if(!child.WaitForExit(5000))child.Kill();}catch{}child.Dispose();}}
 }
}
